sql.basis:
begin read only;
select jsonb_build_object(
'at',now(),'postgres',current_setting('server_version'),
'history',(select jsonb_agg(jsonb_build_object('version',version,'name',name)) from supabase_migrations.schema_migrations where version='20260923081953'),
'readiness',public.get_market_legal_schema_readiness_v1(),
'stripe',(select jsonb_build_object('sandbox_enabled',sandbox_enabled,'live_mode',live_mode) from dv_market_private.market_payment_configuration where singleton),
'counts',jsonb_build_object('listings',(select count(*) from public.market_listings),'offers',(select count(*) from public.market_offers),'deals',(select count(*) from public.market_deals),'orders',(select count(*) from public.market_orders),'contract_snapshots',(select count(*) from dv_market_private.market_contract_snapshots),'withdrawal_drafts',(select count(*) from dv_market_private.market_withdrawal_drafts),'withdrawals',(select count(*) from dv_market_private.market_withdrawals),'payment_attempts',(select count(*) from dv_market_private.market_payment_attempts))
) as evidence; commit;

sql.extra:
begin read only; select jsonb_build_object(
'snapshots',(select jsonb_agg(x) from (select contract_classification,snapshot_version,withdrawal_eligible,count(*) from dv_market_private.market_contract_snapshots group by 1,2,3)x),
'private_grants',(select count(*) from information_schema.role_table_grants where table_schema='dv_market_private' and grantee in ('anon','authenticated')),
'authenticated_private_usage',has_schema_privilege('authenticated','dv_market_private','USAGE'),
'anon_private_usage',has_schema_privilege('anon','dv_market_private','USAGE')
) as evidence; commit;
